-- audi_431_qa_score_aggregates.sql: per-candidate ecommerce_score aggregates (7d ddp_url_verticals)
SELECT
  domain,
  COUNT(*) AS n_urls,
  COUNT(DISTINCT ip) AS n_ips,
  ROUND(APPROX_QUANTILES(ecommerce_score, 100)[OFFSET(50)], 4) AS med_score,
  ROUND(APPROX_QUANTILES(ecommerce_score, 100)[OFFSET(90)], 4) AS p90_score,
  ROUND(AVG(CAST(ecommerce_score >= 0.4 AS INT64)), 4) AS pct_ge_04,
  COUNT(DISTINCT dt) AS days_scored
FROM ddp
WHERE dt BETWEEN '2026-08-02' AND '2026-08-08'
  AND NOT is_in_vertical_mapping
  AND NOT is_whitelist
